fun n p hp =>
  And.casesOn hp fun hpnd right =>
    And.casesOn right fun hp_lt right =>
      And.casesOn right fun hp_gt right =>
        And.casesOn right fun hplen right =>
          And.casesOn right fun hpfq right =>
            And.casesOn right fun hpqprev right =>
              And.casesOn right fun hprec right =>
                And.casesOn right fun hpcut hpsep =>
                  have hgtm := ⋯;
                  let dt := ⋯;
                  let qq := Classical.choose dt;
                  let N' := Classical.choose ⋯;
                  let v := Classical.choose ⋯;
                  And.casesOn ⋯ fun hpref right =>
                    And.casesOn right fun hnd right =>
                      And.casesOn right fun hgrow right =>
                        And.casesOn right fun hqlt right =>
                          And.casesOn right fun hqgt right =>
                            And.casesOn right fun hvpos right =>
                              And.casesOn right fun hveq right =>
                                And.casesOn right fun hvnot right =>
                                  And.casesOn right fun hNlt right =>
                                    And.casesOn right fun hvlt hsep =>
                                      have hpref' := ⋯;
                                      have hnd' := ⋯;
                                      have hgrow' := ⋯;
                                      have hqlt' := ⋯;
                                      have hqgt' := ⋯;
                                      have hvpos' := ⋯;
                                      have hveq' := ⋯;
                                      have hvnot' := ⋯;
                                      have hNlt' := ⋯;
                                      ⋯

